#
# Logic of the code

# The response is generated by the ask command in the user's terminal.
# This Speech.py code will handle the requests as voice inputs and 
# responses to it. It manages overall input-output as a voice assistent.

# importing the libraries, for speech and command execution
import sounddevice
import pyttsx3
import speech_recognition as sr
import subprocess
import time

speak = pyttsx3.init()
recognizer = sr.Recognizer()

# Use Microphone instead of AudioFile
while(True):
    with sr.Microphone() as source:
        # print("Adjusting for ambient noise... Please wait.")
        recognizer.adjust_for_ambient_noise(source, duration=1)
        print("Listening... Speak now!")

        # Records your voice until you stop speaking
        audio_data = recognizer.listen(source)
        print("Processing your voice...")

        try:
            text = recognizer.recognize_google(audio_data)
            print("You said:", text)
            if ("quit" in text):
                exit()
            textFormatted = '"' + text + '"'
            result = subprocess.run(["python", "utils/response.py", textFormatted], capture_output=True, text=True)
            print(result.stdout)
            subprocess.run(["python", "utils/speak.py", result.stdout])
            time.sleep(0.3)
            
        except sr.UnknownValueError:
            print("Google Speech Recognition could not understand what you said.")
        except sr.RequestError as e:
            print(f"Could not request results; {e}")
